import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import deque
def regions(g,bg=8):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                comp=[];q=deque([(i,j)]);seen[i][j]=True
                while q:
                    r,c=q.popleft();comp.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]!=bg and not seen[nr][nc]:
                            seen[nr][nc]=True;q.append((nr,nc))
                out.append(comp)
    return out

def tile_region(g,comp):
    seeds=[(r,c) for r,c in comp if g[r][c]!=0]
    if not seeds: return
    top=min(r for r,c in seeds);left=min(c for r,c in seeds)
    bot=max(r for r,c in seeds);right=max(c for r,c in seeds)
    pat=[[g[r][c] for c in range(left,right+1)] for r in range(top,bot+1)]
    ph,pw=len(pat),len(pat[0])
    for r,c in comp:
        g[r][c]=pat[(r-top)%ph][(c-left)%pw]

def transform(g):
    g=[row[:] for row in g]
    for comp in regions(g): tile_region(g,comp)
    return g

